```python
def max_bitonic_subsequence(arr):
    if not arr:
        return 0

    # Find the maximum sum of an increasing subsequence ending at each index
    inc = [1] * len(arr)
    for i in range(1, len(arr)):
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + 1:
                inc[i] = inc[j] + 1

    # Find the maximum sum of a decreasing subsequence starting at each index
    dec = [1] * len(arr)
    for i in range(len(arr) - 2, -1, -1):
        for j in range(len(arr) - 1, i, -1):
            if arr[i] > arr[j] and dec[i] < dec[j] + 1:
                dec[i] = dec[j] + 1

    # The maximum sum of a bitonic subsequence is the maximum of the product of
    # an increasing subsequence and a decreasing subsequence for all indices
    return max(inc[i] * dec[i] for i in range(len(arr)))
```

