        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def is_sophie_germain_prime(p):
    if not is_prime(p):
        return False
    q = 2 * p + 1
    if not is_prime(q):
        return False
    return True

def is_nsw_prime(n):
    if n < 1:
        return False
    p = is_sophie_germain_prime(n)
    if not p:
        return False
    m = 2 ** p - 1
    if not is_prime(m):
        return False
    return True

def nth_nsw_prime(n):
    count = 0
    i = 1
    while True:
        if is_nsw_prime(i):
            count += 1
            if count == n:
                return i
        i += 1
```
