function maxBitonicSubsequence(arr) {
  // Base case: If the array has only one element, the maximum sum is just that element
  if (arr.length <= 1) return arr[0];

  // Split the array into two parts: the first increasing subsequence and the
  // first decreasing subsequence
  const increasing = arr.slice(0, arr.length - 1);
  const decreasing = arr.slice(arr.length - 1);

  // Recursively find the maximum sum of a bitonic subsequence in each part
  const maxIncreasing = maxBitonicSubsequence(increasing);
  const maxDecreasing = maxBitonicSubsequence(decreasing);

  // Combine the two parts to form a bitonic subsequence
  const bitonic = [...increasing, ...decreasing];

  // Return the maximum sum of the bitonic subsequence
  return Math.max(maxIncreasing, maxDecreasing, bitonic.reduce((a, b) => a + b, 0));
}
```
