```
function isMinHeap(arr) {
  if (arr.length <= 1) {
    return true; // An array with length 0 or 1 is always a min heap
  }

  // Check the root node (first element)
  if (arr[0] >= arr[1]) {
    return false; // Not a min heap since the root node is not the smallest
  }

  // Check the left and right children of the root node
  if (arr[1] >= arr[2] && arr[1] >= arr[3]) {
    return false; // Not a min heap since the left and right children of the root node are not the smallest
  }

  // Recursively check the left and right subtrees
  return isMinHeap(arr.slice(1)) && isMinHeap(arr.slice(2));
}
```
Here's an explanation of how the function works:

